    h,w=len(grid),len(grid[0]); best=(0,-1)  # (side,color)
    for color in range(1,10):
        for s in range(min(h,w),1,-1):
            found=any(all(grid[r][c]==color for r in range(r0,r0+s) for c in range(c0,c0+s))
                      for r0 in range(h-s+1) for c0 in range(w-s+1))
            if found:
                if (s,-color)>(best[0],-best[1]): best=(s,color)
                break
    s,c=best
    return [[c]* (s-1) for _ in range(s-1)]
